import { Group, Mesh, PlaneGeometry, BoxGeometry, PointLight, MeshPhysicalNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, min, max, abs, length, vec2, color, uniform, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#1a1a22' }, { at: 1, hex: '#111116' }],
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = {};
  for (const it of items) byRole[it.role] = it;

  const quoteMarkText = byRole['quote-mark']?.text ?? '"';
  const quoteText = byRole['quote']?.text ?? 'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.';
  const attributionText = byRole['attribution']?.text ?? 'M. OKAFOR';
  const captionText = byRole['caption']?.text ?? 'COLLECTOR SINCE 2019';

  const root = new Group();
  root.userData.handlers = {};

  // ---------- Backdrop (fills the frame so no flat-void region) ----------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshPhysicalNodeMaterial({ roughness: 0.9, metalness: 0.0 });
  const bgTop = color(colors.background);
  const bgBottom = color(colors.surface);
  backdropMat.colorNode = mix(bgTop, bgBottom, uv().y.oneMinus());
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- Panel ----------
  const PANEL_W = 3.4;
  const PANEL_H = 1.9;
  const RADIUS = 0.06;

  const panelGeo = new PlaneGeometry(PANEL_W, PANEL_H, 1, 1);
  const panelMat = new MeshPhysicalNodeMaterial({
    roughness: 0.6,
    metalness: 0.2,
    clearcoat: 0.1,
    transparent: true,
  });

  const stop0 = color(colors.gradientStops?.[0]?.hex ?? '#1a1a22');
  const stop1 = color(colors.gradientStops?.[1]?.hex ?? '#111116');
  const borderColor = color('#26262f');

  const t = uv().y.oneMinus();
  const gradColor = mix(stop0, stop1, t);

  const localX = uv().x.sub(0.5).mul(PANEL_W);
  const localY = uv().y.sub(0.5).mul(PANEL_H);
  const dx = abs(localX).sub(float(PANEL_W / 2 - RADIUS));
  const dy = abs(localY).sub(float(PANEL_H / 2 - RADIUS));
  const outsideVec = vec2(max(dx, 0.0), max(dy, 0.0));
  const outsideDist = length(outsideVec).sub(RADIUS);
  const roundedAlpha = smoothstep(0.006, 0.0, outsideDist);

  const edgeDist = min(
    min(uv().x, uv().y),
    min(uv().x.oneMinus(), uv().y.oneMinus())
  );
  const borderWidth = 0.006 / Math.min(PANEL_W, PANEL_H);
  const borderMask = smoothstep(borderWidth, 0.0, edgeDist);

  const finalColor = mix(gradColor, borderColor, borderMask);

  const fadeUniform = uniform(0.0);
  panelMat.colorNode = finalColor;
  panelMat.opacityNode = roundedAlpha.mul(fadeUniform);

  const panelMesh = new Mesh(panelGeo, panelMat);
  panelMesh.position.set(0, 0, 0);
  root.add(panelMesh);

  // ---------- Quote mark ----------
  const markObj = ctx.fontAtlas.createText(quoteMarkText, {
    fontSize: 62,
    color: colors.accent,
    align: 'left',
  });
  markObj.position.set(-1.7 + 0.5, 0.95 - 0.5, 0.02);
  root.add(markObj);

  // ---------- Quote body ----------
  const quoteObj = ctx.fontAtlas.createText(quoteText, {
    fontSize: 20,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 240,
  });
  quoteObj.position.set(-1.7 + 0.5, 0.02, 0.03);
  root.add(quoteObj);

  // ---------- Accent rule ----------
  const ruleGeo = new BoxGeometry(0.2, 0.02, 0.01);
  const ruleMat = new MeshStandardNodeMaterial({
    roughness: 0.4,
    metalness: 0.1,
  });
  ruleMat.colorNode = color(colors.accent);
  ruleMat.emissiveNode = color(colors.accent).mul(1.4);
  const ruleMesh = new Mesh(ruleGeo, ruleMat);
  ruleMesh.position.set(-1.7 + 0.5 + 0.1, -0.62, 0.03);
  root.add(ruleMesh);

  // ---------- Attribution ----------
  const attribObj = ctx.fontAtlas.createText(attributionText, {
    fontSize: 13,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 0.08 * 13,
  });
  attribObj.position.set(-1.7 + 0.5 + 0.3, -0.7, 0.03);
  root.add(attribObj);

  // ---------- Caption ----------
  const captionObj = ctx.fontAtlas.createText(captionText, {
    fontSize: 9,
    color: '#9a9aa4',
    align: 'left',
    letterSpacingPx: 0.12 * 9,
  });
  captionObj.position.set(-1.7 + 0.5, -0.85, 0.03);
  root.add(captionObj);

  // ---------- Rim / accent light (node-local, cap respected) ----------
  const rimLight = new PointLight(colors.accent, 0.8, 6);
  rimLight.position.set(1.4, 0.8, 2.2);
  root.add(rimLight);

  // ---------- Motion: mount fade-up + weighted settle ----------
  const panelGroup = root; // animate panel content as a whole for the mount
  const startY = panelMesh.position.y;
  panelGroup.position.y = 0.2;

  const tl = gsap.timeline();
  tl.to(fadeUniform, {
    value: 1.0,
    duration: 0.5,
    ease: 'power2.out',
  }, 0);
  tl.to(panelGroup.position, {
    y: startY,
    duration: 0.5,
    ease: 'power2.out',
  }, 0);

  // fade in the text/rule elements alongside the panel
  const fadeTargets = [markObj, quoteObj, attribObj, captionObj, ruleMesh];
  for (const obj of fadeTargets) {
    obj.traverse((child) => {
      if (child.material) {
        child.material.transparent = true;
        child.material.opacity = 0;
      }
    });
  }
  tl.to({}, { duration: 0.0 }, 0); // placeholder anchor
  fadeTargets.forEach((obj) => {
    obj.traverse((child) => {
      if (child.material) {
        tl.to(child.material, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
      }
    });
  });

  // weighted settle on quote mark, starts once panel mount begins to resolve
  markObj.scale.set(1.04, 1.04, 1.04);
  tl.to(markObj.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  }, 0.1);

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    tl.kill();

    backdropGeo.dispose();
    backdropMat.dispose();
    panelGeo.dispose();
    panelMat.dispose();
    ruleGeo.dispose();
    ruleMat.dispose();

    [markObj, quoteObj, attribObj, captionObj].forEach((obj) => {
      obj.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    });

    if (rimLight.parent) rimLight.parent.remove(rimLight);
  };

  return root;
}
